/* PI Champion Season 2 — browser-only demonstration.
 * No real authentication, backend, judge secrets, or official KAsset score data.
 * All data is fictional and stored only in localStorage on this browser.
 */
(() => {
  'use strict';
  const STORE = 'pi-champion-season2-ui-demo-v10';
  const app = document.getElementById('app');
  // Which flow this page serves: index.html = Judge, admin.html = Admin. The two never link to each other.
  const APP = (document.documentElement.dataset.app || window.PI_APP) === 'admin' ? 'admin' : 'judge';
  const ROUTES = APP === 'admin'
    ? {adminAccess:'login', admin:'admin', stage:'results'}
    : {judgeAccess:'login', judgeDashboard:'teams', scoring:'team'};
  const LOGIN = APP === 'admin' ? 'adminAccess' : 'judgeAccess';
  const DASHBOARD = APP === 'admin' ? 'admin' : 'judgeDashboard';
  const {FINAL, DEMO, TEAM_NAMES} = window.PI_CONFIG;
  // Presentation order and score rank are independent: Aurora presents third, but is first in mock scores.
  const MOCK_QUALITY_RANK={};
  const quality = teamId => { const t=state.teams.find(x=>x.id===teamId);return t ? (MOCK_QUALITY_RANK[t.name]??state.teams.indexOf(t)) : 11; };
  const fixed = n => (Number.isFinite(Number(n)) ? Number(n).toFixed(2) : '—');
  const half = n => Math.min(10,Math.max(0,Math.round(n*2)/2));
  const round2 = n => Math.round((n+Number.EPSILON)*100)/100;
  const esc = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
  const icons = {
    arrow:'<path d="M5 12h14m-7-7 7 7-7 7"/>',back:'<path d="m15 18-6-6 6-6"/>',
    lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',
    users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m19 0v-2a4 4 0 0 0-3-3.87M12 3.13a4 4 0 0 1 0 7.75"/><circle cx="9" cy="7" r="4"/>',
    check:'<path d="m4 12 5 5L20 6"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21c0-4.2 3.6-6.5 8-6.5s8 2.3 8 6.5"/>',checkcircle:'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>',
    trophy:'<path d="M8 21h8m-4-4v4M7 3h10v6a5 5 0 0 1-10 0V3ZM7 5H4v2a4 4 0 0 0 4 4m9-6h3v2a4 4 0 0 1-4 4"/>',
    clipboard:'<rect x="5" y="5" width="14" height="17" rx="2"/><rect x="9" y="2" width="6" height="5" rx="1"/><path d="m9 14 2 2 4-4"/>',
    cpu:'<rect x="6" y="6" width="12" height="12" rx="2"/><path d="M9 2v4m6-4v4M9 18v4m6-4v4M2 9h4m-4 6h4m12-6h4m-4 6h4"/><path d="M9 9h6v6H9z"/>',
    trend:'<path d="m3 17 6-6 4 4 8-8m-6 0h6v6"/>',layers:'<path d="m12 3 9 5-9 5-9-5 9-5Zm-9 9 9 5 9-5M3 16l9 5 9-5"/>',
    screen:'<rect x="3" y="3" width="18" height="14" rx="2"/><path d="M8 21h8m-4-4v4m-5-7v-3m4 3V8m4 6v-4"/>',
    spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5L12 2Z"/>',
    laptop:'<rect x="4" y="4" width="16" height="12" rx="2"/><path d="m2 20 2-4h16l2 4H2Z"/>',
    grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
    settings:'<path d="M12 2v3m0 14v3M2 12h3m14 0h3m-17-7 2 2m10 10 2 2m0-14-2 2M7 17l-2 2"/><circle cx="12" cy="12" r="5"/>',
    pencil:'<path d="m16 4 4 4-12 12H4v-4L16 4Z"/>',
    shield:'<path d="m12 22 0-1s8-4 8-10V5l-8-3-8 3v6c0 6 8 10 8 10Z"/>',
    upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v4h16v-4"/>',
    eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',
    fullscreen:'<path d="M9 3H3v6m12-6h6v6M3 15v6h6m12-6v6h-6"/>',
    reset:'<path d="M3 11a9 9 0 1 1 3 7M3 4v7h7"/>',
    warning:'<path d="m12 3 10 18H2L12 3Z"/><path d="M12 9v5m0 4v.1"/>',
    wifi:'<path d="M3 9a15 15 0 0 1 18 0m-15 4a10 10 0 0 1 12 0m-9 4a5 5 0 0 1 6 0m-3 3v.1"/>',
    download:'<path d="M12 3v12m-4-4 4 4 4-4M4 18v3h16v-3"/>',
  };
  const icon = (name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.grid}</svg>`;
  let ribbonId = 0;
  // Illustrated static fallback with ribbon-shaped surfaces, layered normals and glints.
  // On the landing and winner screens, WebGL animates an additional 3D ribbon above this.
  const wave=()=>{const id=`ribbon-${++ribbonId}`;return `<svg class="wave-art" viewBox="0 0 760 360" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><defs>
    <linearGradient id="${id}-rear" x1="0" x2="1" y1="0" y2="1"><stop offset="0%" stop-color="#dff4ea" stop-opacity=".03"/><stop offset="32%" stop-color="#46c5c0" stop-opacity=".68"/><stop offset="62%" stop-color="#065b58" stop-opacity=".75"/><stop offset="100%" stop-color="#b1e3cb" stop-opacity=".25"/></linearGradient>
    <linearGradient id="${id}-body" x1="0" x2=".88" y1=".18" y2="1"><stop offset="0%" stop-color="#c8ecdb" stop-opacity=".72"/><stop offset="23%" stop-color="#38b5b1" stop-opacity=".68"/><stop offset="55%" stop-color="#035654" stop-opacity=".88"/><stop offset="83%" stop-color="#037975" stop-opacity=".81"/><stop offset="100%" stop-color="#b4e5cd" stop-opacity=".64"/></linearGradient>
    <linearGradient id="${id}-glint" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#e9f7f0" stop-opacity=".9"/><stop offset="50%" stop-color="#b6e5ce" stop-opacity=".2"/><stop offset="100%" stop-color="#ffffff" stop-opacity=".9"/></linearGradient>
    <filter id="${id}-glow" x="-20%" y="-50%" width="150%" height="190%"><feGaussianBlur stdDeviation="8"/></filter>
    </defs>
    <path d="M-30 250 C145 55 247 127 358 204 C520 311 592 58 808 106 L808 171 C615 100 544 343 348 255 C202 188 118 123 -30 312Z" fill="url(#${id}-rear)" opacity=".55"/>
    <path class="ribbon-core" d="M-30 263 C121 113 208 177 358 226 C529 284 610 63 800 101 L800 151 C612 112 548 337 358 269 C196 211 122 161 -30 305Z" fill="url(#${id}-body)"/>
    <path d="M-25 250 C130 98 210 169 356 221 C524 272 606 63 797 96" fill="none" stroke="#def4e9" stroke-width="10" opacity=".60" filter="url(#${id}-glow)"/>
    <path d="M-25 250 C130 98 210 169 356 221 C524 272 606 63 797 96" fill="none" stroke="url(#${id}-glint)" stroke-width="2.8" opacity=".9"/>
    ${Array.from({length:12},(_,i)=>{const d=i*3;return `<path d="M-32 ${266+d} C121 ${116+d*.9} 208 ${180+d*.68} 358 ${230+d*.78} C529 ${287+d*.5} 610 ${69+d*.35} 800 ${104+d*.56}" fill="none" stroke="${i%3===0?'#cdedde':'#c9ecdb'}" stroke-width="${i%4===0?1.05:.55}" opacity="${(.13+i*.019).toFixed(2)}"/>`;}).join('')}
    </svg>`;};
  const brand=()=>`<button type="button" class="brand" data-action="brand-home" aria-label="KAsset · ไปหน้าหลัก"><img class="brand-logo" src="./assets/img/kasset-logo.webp" alt="KAsset" width="480" height="123" decoding="async"/><span class="brand-divider"></span><span class="event-name">PI Champion<br/><em>Season 2</em></span></button>`;
  const badge=(s,kind='')=>`<span class="pill ${kind}">${esc(s)}</span>`;
  const now=new Date();
  const defaultDemo=(idx)=>({pain_point:round2(9.0-idx*.12),process_approach:round2(8.95-idx*.13),results:round2(9.05-idx*.13),innovation:round2(8.9-idx*.12),benefits:round2(8.85-idx*.11)});
  const initial=()=>({
    screen:'home',mode:'judge',filter:'all',adminTab:'overview',activeTeamId:3,stageShot:1,
    published:false,preview:false,demoWeight:20,locked:[],toast:'',dialog:null,codeInput:'',
    teams:TEAM_NAMES.map((name,idx)=>({id:idx+1,name})),
    demoScores:Object.fromEntries(TEAM_NAMES.map((name,idx)=>[idx+1,defaultDemo(MOCK_QUALITY_RANK[name]??idx)])),
    judgeScores:{},newTeamName:'',
  });
  let state=initial();
  try {const saved=JSON.parse(localStorage.getItem(STORE)||'null');if(saved && Array.isArray(saved.teams)) state={...initial(),...saved,dialog:null,toast:'',codeInput:''};} catch(err) {console.warn('Demo state reset',err);}

  // ---------- Live mode: same-origin server (server/server.mjs). Artifact / static hosting stays in demo mode. ----------
  const LIVE={on:false,token:null,me:null,judges:[],confirmed:{},status:{},rev:0,eventKey:'',pushTimer:null,pushing:false,pushAgain:false,dirty:new Set(),draftTimers:{},pollTimer:null};
  const TOKEN_KEY='pi-champion-s2-live-token-'+APP;
  try{LIVE.token=localStorage.getItem(TOKEN_KEY);}catch(e){}
  function setToken(t){LIVE.token=t;try{t?localStorage.setItem(TOKEN_KEY,t):localStorage.removeItem(TOKEN_KEY);}catch(e){}}
  async function apiCall(method,url,body){
    const r=await fetch(url,{method,cache:'no-store',headers:{'Content-Type':'application/json',...(LIVE.token?{Authorization:'Bearer '+LIVE.token}:{})},body:body===undefined?undefined:JSON.stringify(body)});
    let data={};try{data=await r.json();}catch(e){}
    if(r.status===401&&url!=='/api/login'){liveSignedOut('หมดเวลาเข้าสู่ระบบ กรุณาใส่รหัสอีกครั้ง');}
    if(!r.ok){const err=new Error(data.error||('เชื่อมต่อ server ไม่สำเร็จ ('+r.status+')'));err.status=r.status;err.data=data;throw err;}
    return data;
  }
  function liveSignedOut(message){setToken(null);state.auth={...(state.auth||{}),[APP]:false};state.screen=LOGIN;writeHash(false);state.toast=message||'';render();}
  const eventKeyOf=e=>JSON.stringify([e.teams,e.demoScores,e.demoWeight,e.locked,e.published]);
  function applyJudge(d){
    LIVE.me=d.judge;state.teams=d.event.teams;state.locked=d.event.locked;state.published=d.event.published;
    const next={};for(const [id,r] of Object.entries(d.scores||{}))next[id]={draft:r.draft||{},confirmed:r.confirmed||null};
    for(const id of LIVE.dirty)if(state.judgeScores[id])next[id]=state.judgeScores[id];
    state.judgeScores=next;
  }
  function applyAdmin(d){
    LIVE.judges=d.judges||[];LIVE.confirmed=d.confirmed||{};LIVE.status=d.status||{};LIVE.rev=d.event.rev;
    state.teams=d.event.teams;state.demoScores=d.event.demoScores||{};state.demoWeight=d.event.demoWeight;state.locked=d.event.locked;state.published=d.event.published;
    LIVE.eventKey=eventKeyOf(d.event);
  }
  async function liveRefresh(){
    if(!LIVE.on||!LIVE.token)return;
    if(APP==='judge')applyJudge(await apiCall('GET','/api/judge/state'));
    else if(!LIVE.pushing&&!LIVE.pushTimer)applyAdmin(await apiCall('GET','/api/admin/state'));
  }
  function viewKey(){return JSON.stringify([state.teams,state.locked,state.published,state.demoScores,state.demoWeight,state.judgeScores,LIVE.confirmed,LIVE.status]);}
  function startPolling(){
    clearInterval(LIVE.pollTimer);
    LIVE.pollTimer=setInterval(async()=>{
      if(!LIVE.token||document.hidden)return;
      const before=viewKey();
      try{await liveRefresh();}catch(e){return;}
      const typing=document.activeElement&&/^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement.tagName);
      if(viewKey()!==before&&!typing&&!state.dialog)render();
    },APP==='admin'?3000:8000);
  }
  async function liveLogin(){
    const code=(state.codeInput||'').trim();if(!code)return toast('กรุณากรอกรหัส');
    try{
      const d=await apiCall('POST','/api/login',{role:APP,code});
      setToken(d.token);LIVE.me=d.judge||null;state.auth={...(state.auth||{}),[APP]:true};state.codeInput='';
      await liveRefresh();changeScreen(DASHBOARD);
    }catch(e){toast(e.message);}
  }
  async function liveLogout(){try{await apiCall('POST','/api/logout');}catch(e){}setToken(null);state.auth={...(state.auth||{}),[APP]:false};changeScreen(LOGIN);}
  function queueDraft(teamId){
    LIVE.dirty.add(String(teamId));clearTimeout(LIVE.draftTimers[teamId]);
    LIVE.draftTimers[teamId]=setTimeout(async()=>{
      delete LIVE.draftTimers[teamId];
      try{const d=await apiCall('PUT','/api/judge/scores',{teamId,draft:record(teamId).draft});LIVE.dirty.delete(String(teamId));const r=d.scores?.[teamId];if(r&&state.judgeScores[teamId])state.judgeScores[teamId].confirmed=r.confirmed||null;}
      catch(e){LIVE.dirty.delete(String(teamId));toast(e.message);try{await liveRefresh();render();}catch(_){}}
    },500);
  }
  async function liveSubmit(d){
    const r=record(d.teamId);if(myTotal(r.draft)===null)return toast('กรุณากรอกคะแนนทุกเกณฑ์ก่อนยืนยัน');
    clearTimeout(LIVE.draftTimers[d.teamId]);delete LIVE.draftTimers[d.teamId];
    try{
      const res=await apiCall('PUT','/api/judge/scores',{teamId:d.teamId,draft:r.draft,submit:true});
      LIVE.dirty.delete(String(d.teamId));const x=res.scores?.[d.teamId];state.judgeScores[d.teamId]={draft:x.draft,confirmed:x.confirmed};
      state.dialog=null;changeScreen('judgeDashboard');toast(d.isEdit?'บันทึกการแก้ไขคะแนนแล้ว':'ส่งคะแนนเรียบร้อยแล้ว');
    }catch(e){state.dialog=null;toast(e.message);try{await liveRefresh();render();}catch(_){}}
  }
  async function liveResetScores(){
    if((state.resetConfirm||'').trim().toUpperCase()!=='RESET')return toast('พิมพ์ RESET เพื่อยืนยัน');
    clearTimeout(LIVE.pushTimer);LIVE.pushTimer=null;
    try{
      const d=await apiCall('POST','/api/admin/reset-scores',{confirm:'RESET'});
      applyAdmin(d);state.resetConfirm='';state.preview=false;state.dialog=null;changeScreen('admin');
      toast(`ล้างคะแนนกรรมการแล้ว (${d.cleared} รายการ) · ปลด Lock ทุกทีม · สำรองไว้ที่ data/${d.backup}`);
    }catch(e){state.dialog=null;toast(e.message);try{applyAdmin(await apiCall('GET','/api/admin/state'));}catch(_){} render();}
  }
  function queueAdminPush(){
    if(!LIVE.on||APP!=='admin'||!authed())return;
    if(eventKeyOf(state)===LIVE.eventKey)return;
    clearTimeout(LIVE.pushTimer);LIVE.pushTimer=setTimeout(pushAdmin,250);
  }
  async function pushAdmin(){
    LIVE.pushTimer=null;
    if(LIVE.pushing){LIVE.pushAgain=true;return;}
    LIVE.pushing=true;
    try{applyAdmin(await apiCall('PUT','/api/admin/event',{rev:LIVE.rev,teams:state.teams,demoScores:state.demoScores,demoWeight:state.demoWeight,locked:state.locked,published:state.published}));}
    catch(e){toast(e.message);LIVE.pushing=false;try{applyAdmin(await apiCall('GET','/api/admin/state'));}catch(_){} if(state.screen==='stage'&&!state.published)state.screen='admin';render();return;}
    LIVE.pushing=false;
    if(LIVE.pushAgain){LIVE.pushAgain=false;queueAdminPush();}
    render();
  }
  const REAL=()=>LIVE.on||!!ACCESS();
  const JUDGE_TOTAL=()=>LIVE.on?LIVE.judges.length:ACCESS()?ACCESS().filter(x=>x.role==='judge').length:15;
  // Static build with issued codes: scores of every judge who signed in on this browser
  function localJudgeScores(){const by={...(state.scoresByJudge||{})};if(state.judgeId)by[state.judgeId]=state.judgeScores;return by;}
  function localConfirmed(teamId){const by=localJudgeScores();return (ACCESS()||[]).filter(x=>x.role==='judge').map(j=>by[j.id]?.[teamId]?.confirmed).filter(c=>countScores(c)===FINAL.length);}
  async function detectLive(){
    if(!/^https?:$/.test(location.protocol))return false;
    try{
      const ctl=new AbortController();const timer=setTimeout(()=>ctl.abort(),2500);
      const r=await fetch('/api/health',{signal:ctl.signal,cache:'no-store'});clearTimeout(timer);
      if(!r.ok)return false;const d=await r.json();if(d.mode!=='live')return false;
    }catch(e){return false;}
    LIVE.on=true;document.documentElement.dataset.live='1';
    state.judgeScores={};state.locked=[];state.published=false;state.demoScores={};state.preview=false;
    state.auth={...(state.auth||{}),[APP]:!!LIVE.token};
    if(LIVE.token){try{await liveRefresh();}catch(e){if(e.status!==401){state.toast=e.message;}}}
    startPolling();
    return true;
  }
  // Issued codes for static/artifact use: assets/js/access-codes.js (not in git) sets window.PI_ACCESS
  // to [{role,id,name,hash}] where hash = SHA-256('pi-s2:' + CODE). Without it the demo codes apply.
  const ACCESS=()=>Array.isArray(window.PI_ACCESS)&&window.PI_ACCESS.length?window.PI_ACCESS:null;
  async function sha256Hex(text){const buf=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text));return Array.from(new Uint8Array(buf),b=>b.toString(16).padStart(2,'0')).join('');}
  async function staticLogin(){
    const code=(state.codeInput||'').trim().toUpperCase();if(!code)return toast('กรุณากรอกรหัส');
    let who=null;
    try{const h=await sha256Hex('pi-s2:'+code);who=ACCESS().find(x=>x.role===APP&&x.hash===h)||null;}catch(e){return toast('เบราว์เซอร์นี้ตรวจรหัสไม่ได้');}
    if(!who)return toast(APP==='admin'?'รหัส Admin ไม่ถูกต้อง':'รหัสกรรมการไม่ถูกต้อง');
    if(APP==='judge'){const by={...(state.scoresByJudge||{})};if(state.judgeId)by[state.judgeId]=state.judgeScores;state.scoresByJudge=by;state.judgeId=who.id;state.judgeName=who.name;state.judgeScores=by[who.id]||{};}
    state.auth={...(state.auth||{}),[APP]:true};state.codeInput='';changeScreen(DASHBOARD);
  }
  function save(){queueAdminPush();if(LIVE.on)return;try {const store={...state,dialog:null,toast:'',codeInput:''};localStorage.setItem(STORE,JSON.stringify(store));} catch(e){console.warn('Unable to store prototype state',e);}}
  function record(teamId){return state.judgeScores[teamId]||{draft:{},confirmed:null};}
  const isValidScore = v => typeof v==='number'&&Number.isFinite(v)&&v>=0&&v<=10&&Number.isInteger(v*2);
  function countScores(scores){return FINAL.filter(c=>isValidScore(scores?.[c.id])).length;}
  function isComplete(teamId){return countScores(record(teamId).confirmed)===FINAL.length;}
  function isPending(teamId){const r=record(teamId);return !!r.confirmed && FINAL.some(c=>(r.draft?.[c.id]??null)!==(r.confirmed?.[c.id]??null));}
  function judgeStatus(teamId){const r=record(teamId);if(state.locked.includes(teamId))return ['Locked','dark'];if(isPending(teamId))return ['Pending Changes','warn'];if(isComplete(teamId))return ['Completed','good'];if(countScores(r.draft)>0)return ['Draft','warn'];return ['Not Started',''];}
  function myTotal(scores){if(countScores(scores)!==FINAL.length)return null;return round2(FINAL.reduce((sum,c)=>sum+scores[c.id]*c.weight/10,0));}
  function simulatedScore(idx,judge,cidx){const base=9.2-(idx*.14);const bias=[0.05,-.1,.04,-.08,.02,-.03][cidx]||0;const noise=(((judge*5+cidx*3+idx*5)%7)-3)*.11;return half(base+bias+noise);}
  function sampleScores(teamId,judge=1){return Object.fromEntries(FINAL.map((c,i)=>[c.id,simulatedScore(quality(teamId),judge,i)]));}
  function judgeCompletionCount(teamId){if(LIVE.on)return Object.keys(LIVE.confirmed[teamId]||{}).length;if(ACCESS())return localConfirmed(teamId).length;return 14+(isComplete(teamId)?1:0);} // fictional 14 pre-completed judges in the demo
  function averageFinalCriterion(teamId,cId){if(REAL()){const v=(LIVE.on?Object.values(LIVE.confirmed[teamId]||{}):localConfirmed(teamId)).map(x=>Number(x[cId])).filter(Number.isFinite);return v.length?v.reduce((a,b)=>a+b,0)/v.length:0;}const cidx=FINAL.findIndex(c=>c.id===cId);let sum=0;for(let j=2;j<=15;j++)sum+=simulatedScore(quality(teamId),j,cidx);let n=14;const user=record(teamId).confirmed?.[cId];if(isValidScore(user)){sum+=user;n++;}return sum/n;}
  function finalScore(teamId){return FINAL.reduce((sum,c)=>sum+averageFinalCriterion(teamId,c.id)*c.weight/10,0);}
  function demoScore(teamId){const avgs=state.demoScores[teamId]||(LIVE.on?{}:defaultDemo(0));return DEMO.reduce((sum,c)=>sum+(Number(avgs[c.id])||0)*c.weight/10,0);}
  function overall(teamId){return round2(demoScore(teamId)*state.demoWeight/100+finalScore(teamId)*(100-state.demoWeight)/100);}
  function ranked(){const a=state.teams.map(t=>({...t,demo:demoScore(t.id),final:finalScore(t.id),overall:overall(t.id)}));a.sort((x,y)=>y.overall-x.overall||x.id-y.id);let rank=0;return a.map((t,i)=>{if(i===0||t.overall!==a[i-1].overall)rank=i+1;return {...t,rank};});}
  function hasTopTie(){const a=ranked();return a.some((x,i)=>i<4 && i>0 && x.overall===a[i-1].overall && (i<=3));}
  function allowedToLock(teamId){return JUDGE_TOTAL()>0&&judgeCompletionCount(teamId)===JUDGE_TOTAL();}
  function setScore(teamId,cId,value){if(state.published||state.locked.includes(teamId))return toast('ทีมนี้ถูกล็อก ไม่สามารถแก้ไขคะแนนได้');const r=record(teamId);const base=r.draft&&Object.keys(r.draft).length?r.draft:(r.confirmed||{});state.judgeScores[teamId]={confirmed:r.confirmed||null,draft:{...base,[cId]:value}};state.toast='';if(LIVE.on)queueDraft(teamId);save();render();}
  function toast(message){state.toast=message;render();}
  function authed(){return !!(state.auth&&state.auth[APP]);}
  function allowedScreen(screen){
    if(!Object.prototype.hasOwnProperty.call(ROUTES,screen)) screen=DASHBOARD;
    if(!authed()) return LOGIN;
    if(screen===LOGIN) return DASHBOARD;
    if(screen==='scoring' && !state.teams.some(t=>t.id===state.activeTeamId)) return DASHBOARD;
    return screen;
  }
  function hashFor(screen){return screen==='scoring'?`#team-${state.activeTeamId}`:`#${ROUTES[screen]}`;}
  function screenFromHash(){
    const h=decodeURIComponent((location.hash||'').slice(1));
    const m=/^team-(\d+)$/.exec(h);
    if(m && APP==='judge'){state.activeTeamId=Number(m[1]);return 'scoring';}
    return Object.keys(ROUTES).find(k=>ROUTES[k]===h)||null;
  }
  function writeHash(push){
    const h=hashFor(state.screen);if(location.hash===h)return;
    try{history[push?'pushState':'replaceState'](null,'',h);}catch(e){try{location.hash=h;}catch(_){}}
  }
  function changeScreen(screen){state.screen=allowedScreen(screen);state.toast='';state.dialog=null;writeHash(true);save();render();window.scrollTo({top:0,behavior:'instant'});}
  function applyRoute(){const want=screenFromHash();state.screen=allowedScreen(want||state.screen);state.dialog=null;writeHash(false);save();render();window.scrollTo({top:0,behavior:'instant'});}
  window.addEventListener('popstate',applyRoute);
  window.addEventListener('hashchange',applyRoute);
  function selectTeam(id){state.activeTeamId=id;changeScreen('scoring');}
  function openDialog(type,teamId){state.dialog={type,teamId};render();}
  function closeDialog(){state.dialog=null;render();}
  function confirmDialog(){
    const d=state.dialog;if(!d)return;
    if(LIVE.on&&d.type==='submit'){liveSubmit(d);return;}
    if(REAL()&&d.type==='simulate'){state.dialog=null;return toast('ปิดการเติมคะแนนจำลองเมื่อใช้รหัสจริง');}
    if(LIVE.on&&d.type==='reset'){liveResetScores();return;}
    if(LIVE.on&&d.type==='simulate'){state.dialog=null;return toast('ปิดฟังก์ชันนี้ในระบบจริง');}
    switch(d.type){
      case 'submit': {
        const r=record(d.teamId);if(myTotal(r.draft)===null)return toast('กรุณากรอกคะแนนทุกเกณฑ์ก่อนยืนยัน');
        if(state.locked.includes(d.teamId)||state.published)return toast('ทีมนี้ถูกล็อกแล้ว');
        state.judgeScores[d.teamId]={confirmed:{...r.draft},draft:{...r.draft}};
        state.screen='judgeDashboard';state.toast=d.isEdit?'บันทึก Save Changes สำเร็จ (ข้อมูลจำลอง)':'ยืนยันคะแนนสำเร็จ (ข้อมูลจำลอง)';break;
      }
      case 'simulate': {
        state.teams.forEach(t=>{if(!isComplete(t.id)&&!state.locked.includes(t.id)){const sample=sampleScores(t.id,1);state.judgeScores[t.id]={confirmed:sample,draft:{...sample}};}});
        state.toast='เติมคะแนนสมมติของกรรมการ Demo ให้ครบแล้ว';break;
      }
      case 'lockTeam': {
        if(!allowedToLock(d.teamId)){state.toast='ยังมีกรรมการส่งไม่ครบ จึง Lock ไม่ได้';break;}
        if(!state.locked.includes(d.teamId))state.locked.push(d.teamId);
        state.toast='Lock ทีมสำเร็จ (Demo)';break;
      }
      case 'unlockTeam': {
        if(state.published){state.toast='ประกาศผลแล้ว จึงไม่สามารถ Unlock ได้';break;}
        state.locked=state.locked.filter(id=>id!==d.teamId);state.toast='Unlock ทีมสำเร็จ (Demo)';break;
      }
      case 'lockAll': {
        if(!state.teams.every(t=>allowedToLock(t.id))){state.toast='ต้องมี Confirmed Submission ครบทุกทีมก่อน Lock All';break;}
        state.locked=state.teams.map(t=>t.id);state.toast='Lock ทุกทีมสำเร็จ (Demo)';break;
      }
      case 'publish': {
        if(!state.teams.every(t=>state.locked.includes(t.id)))return toast('ต้อง Lock ทุกทีมก่อน Publish');
        if(hasTopTie())return toast('พบคะแนนเสมอที่กระทบ Top 3 กรุณาดำเนินการ Tie Review');
        state.published=true;state.preview=false;state.stageShot=1;state.screen='stage';state.toast='เผยแพร่ผลคะแนนจำลองแล้ว';break;
      }
      case 'reset':{const auth=state.auth;state=initial();state.auth=auth;state.screen=DASHBOARD;state.toast='รีเซ็ต Demo เรียบร้อย';break;}
      case 'import': {
        d.rows.forEach(({teamId,scores})=>{state.demoScores[teamId]={...scores};});
        state.toast=`นำเข้าคะแนน Demo จาก CSV สำเร็จ ${d.rows.length} ทีม`;break;
      }
    }
    state.dialog=null;state.screen=allowedScreen(state.screen);writeHash(true);save();render();if(d.type==='publish'||d.type==='submit')window.scrollTo({top:0,behavior:'instant'});
  }
  function metaHead(){
    if(state.screen==='judgeAccess'||state.screen==='adminAccess')return '';
    if(state.screen==='home'){
      return `<header class="site-head site-head-home"><div class="header-inner home-head-inner">${brand()}<div class="head-right"><nav class="header-nav home-nav" aria-label="Primary"><a class="head-link active" href="#home-cover">Home</a><a class="head-link" href="#home-about">About the Competition</a><a class="head-link" href="#how-it-works">How It Works</a><a class="head-link" href="#faq">FAQ</a></nav></div></div></header>`;
    }
    const who=APP==='admin'?'Admin':(LIVE.me?.name||state.judgeName||'กรรมการ');
    const nav=APP==='admin'&&authed()?[['admin','ภาพรวม'],['stage','ประกาศผล']]:[];
    return `<header class="site-head app-header"><div class="header-inner">${brand()}<div class="head-right">${nav.length?`<nav class="header-nav" aria-label="เมนู">${nav.map(([sc,l])=>`<button class="head-link ${state.screen===sc?'active':''}" data-action="head-nav" data-target="${sc}">${l}</button>`).join('')}</nav>`:''}${LIVE.on?'':`<span class="mode-tag">${ACCESS()?'TEST MODE':'DEMO'}</span>`}${authed()?`<span class="head-user">${icon('user')}${esc(who)}</span><button type="button" class="btn small btn--on-dark" data-action="logout">ออกจากระบบ</button>`:''}</div></div></header>`;
  }
  function home(){return `<div class="landing-shell"><section id="home-cover" class="landing-hero"><div class="landing-glow landing-glow-a"></div><div class="landing-glow landing-glow-b"></div><div class="landing-grid"><div class="cover-copy"><div class="cover-kicker-row"><span class="cover-line"></span><span class="cover-kicker">KAsset AI Innovation Competition</span>${badge('Final Day','champ')}</div><h1 class="cover-title"><span>PI Champion</span><em>Season 2</em></h1><p class="cover-tagline">Turning AI ideas into real impact.</p><span class="cover-underline"></span><p class="cover-description">Experience the final stage of PI Champion Season 2 — where expert judges evaluate, scores come to life, and the winners are revealed.</p><div class="hero-actions cover-actions"><button class="btn primary" data-action="access-judge">Enter Scoring ${icon('arrow')}</button><button class="btn outline" data-action="preview-stage">${icon('eye')} View Demo</button></div></div><div class="cover-art"><img class="hero-ribbon-image" src="data:image/webp;base64," alt="" loading="eager" decoding="async" fetchpriority="high" /><div class="hero-art-shine" aria-hidden="true"></div></div></div></section><section id="home-about" class="home-panel panel-pills"><button class="pillar-card" data-action="access-judge"><span class="pillar-icon">${icon('users')}</span><span class="pillar-body"><strong>Judge Scoring</strong><small>Evaluate and score AI innovations with a seamless, real-time experience.</small></span></button><button class="pillar-card" data-action="access-admin"><span class="pillar-icon">${icon('settings')}</span><span class="pillar-body"><strong>Admin Control</strong><small>Manage teams, judges, criteria, and competition settings with ease.</small></span></button><button class="pillar-card" data-action="preview-stage"><span class="pillar-icon">${icon('trophy')}</span><span class="pillar-body"><strong>Results Reveal</strong><small>Share Top 3 winners first, then display the detailed scoring breakdown.</small></span></button></section><section id="how-it-works" class="home-story-grid"><div class="home-panel story-panel"><div class="section-kicker">How it works</div><h2>The final-day judging flow</h2><div class="story-steps"><div class="story-step"><span>01</span><div><strong>Enter Scoring</strong><p>Judges sign in with their private code and score every team on every criterion.</p></div></div><div class="story-step"><span>02</span><div><strong>Review & Confirm</strong><p>Scores are drafted automatically, reviewed in a confirmation modal, and then submitted.</p></div></div><div class="story-step"><span>03</span><div><strong>Reveal the Winners</strong><p>Admins lock all teams, publish the results, and present Top 3 before the full table.</p></div></div></div></div><div id="faq" class="home-panel faq-panel"><div class="section-kicker">FAQ</div><h2>Quick answers</h2><div class="faq-item"><strong>Who can score?</strong><p>Only official judges on Final Day. Judges do not see each other’s scores.</p></div><div class="faq-item"><strong>What score range is used?</strong><p>Each criterion is scored from 0–10 in 0.5 increments using direct score buttons.</p></div><div class="faq-item"><strong>When are results shown?</strong><p>Results appear only after Admin locks all teams and publishes the final reveal.</p></div></div></section><p class="footer-note">* This is a product prototype for PI Champion Season 2. Branding, teams, criteria, and scores shown here are demo content for design and workflow testing.</p></div>`;}
  function access(){const admin=APP==='admin';const demo=!REAL();
    return `<section class="login-split">
      <div class="login-brand">
        <img class="login-logo" src="./assets/img/kasset-logo.webp" alt="KAsset" width="480" height="123"/>
        <h1 class="login-title">PI Champion<span>Season 2</span></h1>
        <img class="login-two" src="./assets/img/season-2.webp" alt="" aria-hidden="true" decoding="async"/>
      </div>
      <div class="login-panel">
        <div class="login-kicker">${admin?'ADMIN CONTROL':'FINAL DAY'}</div>
        <form class="login-form" onsubmit="return false" autocomplete="off">
          <span class="login-rule" aria-hidden="true"></span>
          <h2>${admin?'เข้าสู่ระบบ Admin':'เข้าสู่ระบบกรรมการ'}</h2>
          <p class="login-sub">${admin?'ใช้ Admin Code สำหรับจัดการการแข่งขัน':'ใช้ Judge Code ที่ได้รับจากผู้จัดงาน'}</p>
          <label class="login-label" for="demo-code">${admin?'Admin Code':'Judge Code'}</label>
          <input id="demo-code" class="login-input" data-input="code" value="${esc(state.codeInput)}" placeholder="${admin?'กรอกรหัส Admin':'กรอกรหัสกรรมการ'}" autocomplete="off" autocapitalize="characters" spellcheck="false" enterkeyhint="go"/>
          ${demo?`<div class="access-hint">${icon('shield')} รหัสสำหรับ Demo: <strong>${admin?'ADMINDEMO':'JUDGE01'}</strong> <button type="button" class="login-link" data-action="fill-code" data-code="${admin?'ADMINDEMO':'JUDGE01'}">ใส่ให้</button></div>`:''}
          <button type="button" class="login-btn" data-action="login" data-role="${admin?'admin':'judge'}"><span>เข้าสู่ระบบ</span>${icon('arrow')}</button>
          <p class="login-help">ไม่มีรหัส? <span class="login-contact">ติดต่อผู้จัดงาน</span></p>
          <p class="login-note">${admin?'คะแนนรายกรรมการไม่ถูกเปิดเผยต่อสาธารณะ':'กรรมการแต่ละท่านเห็นเฉพาะคะแนนของตนเอง'}</p>
        </form>
      </div>
    </section>`;}

  // ===== Shared UI components (used by both Judge and Admin) =====
  // pageHead: title + subtitle, optional actions (right) or Season-2 art.
  function pageHead({title,sub='',actions='',art=false}){
    return `<header class="page-head"><div class="page-head-text"><h1 class="page-title">${title}</h1>${sub?`<p class="page-sub">${sub}</p>`:''}</div>${actions?`<div class="page-actions">${actions}</div>`:''}${art?'<img class="page-art" src="./assets/img/season-2.webp" alt="" aria-hidden="true"/>':''}</header>`;
  }
  // summaryBar: big count line + progress bar + right-hand detail.
  function summaryBar({label,done,total,detail='',unit='ทีม'}){
    const pct=total?Math.round(done/total*100):0;
    return `<div class="summary"><div class="summary-top"><h2>${label} <b>${done}</b> จาก ${total} ${unit}</h2>${detail?`<span>${detail}</span>`:''}</div>${progressBar(done,total,label)}</div>`;
  }
  function progressBar(done,total,label='',size=''){const pct=total?Math.round(done/total*100):0;return `<div class="progress ${size}" role="progressbar" aria-valuemin="0" aria-valuemax="${total}" aria-valuenow="${done}" aria-label="${esc(label)}"><span style="width:${pct}%"></span></div>`;}
  // tabs: underline tab row. items = [[key,label,count?]]
  function tabsRow(items,active,action,attr){
    return `<div class="tabs" role="tablist">${items.map(([k,v,n])=>`<button type="button" role="tab" aria-selected="${active===k}" class="tab ${active===k?'on':''}" data-action="${action}" data-${attr}="${k}">${v}${n!==undefined?` ${n}`:''}</button>`).join('')}</div>`;
  }
  function judgeDashboard(){
    const rows=state.teams.map((t,i)=>{const [status]=judgeStatus(t.id);return {t,i,status};});
    const isDraft=x=>x.status==='Draft'||x.status==='Pending Changes';
    const counts={all:rows.length,notstarted:rows.filter(x=>x.status==='Not Started').length,draft:rows.filter(isDraft).length,completed:rows.filter(x=>isComplete(x.t.id)).length};
    const filter=['all','notstarted','draft','completed'].includes(state.filter)?state.filter:'all';
    const visible=rows.filter(x=>filter==='all'||(filter==='completed'&&isComplete(x.t.id))||(filter==='draft'&&isDraft(x))||(filter==='notstarted'&&x.status==='Not Started'));
    const label={'Locked':['ล็อกแล้ว','locked','ดูคะแนน'],'Pending Changes':['แก้ไขแล้ว ยังไม่ส่ง','draft','ส่งการแก้ไข'],'Completed':['ส่งแล้ว','done','ดูหรือแก้ไข'],'Draft':['แบบร่าง','draft','ให้คะแนนต่อ'],'Not Started':['ยังไม่เริ่ม','todo','เริ่มให้คะแนน']};
    return `${pageHead({title:'ทีมที่ต้องประเมิน',sub:'เรียงตามลำดับนำเสนอ • เลือกประเมินทีมใดก่อนก็ได้',art:true})}
      ${summaryBar({label:'ส่งคะแนนแล้ว',done:counts.completed,total:counts.all,detail:`ยังไม่เริ่ม ${counts.notstarted} ทีม · แบบร่าง ${counts.draft} ทีม`})}
      ${tabsRow([['all','ทั้งหมด',counts.all],['notstarted','ยังไม่เริ่ม',counts.notstarted],['draft','แบบร่าง',counts.draft],['completed','ส่งแล้ว',counts.completed]],filter,'filter','filter')}
      <div class="card table-card"><table class="data-table data-table--stack data-table--rows">
        <thead><tr><th class="col-order">ลำดับนำเสนอ</th><th>ทีม</th><th class="col-status">สถานะ</th><th class="col-score">คะแนนที่ส่ง</th><th class="col-act">การทำงาน</th></tr></thead>
        <tbody>${visible.map(({t,i,status})=>{const [txt,cls,act]=label[status]||label['Not Started'];const total=isComplete(t.id)?myTotal(record(t.id).confirmed):null;
          return `<tr class="is-${cls}" data-action="select-team" data-id="${t.id}">
            <td class="col-order"><span class="order-no">${String(i+1).padStart(2,'0')}</span></td>
            <td class="col-name"><strong>${esc(t.name)}</strong></td>
            <td class="col-status"><span class="status status--${cls}">${cls==='done'?icon('check'):cls==='locked'?icon('lock'):''}${txt}</span></td>
            <td class="col-score${total===null?' is-empty':''}">${total===null?'—':`${fixed(total)} / 100`}</td>
            <td class="col-act"><button type="button" class="link-btn" data-action="select-team" data-id="${t.id}">${act}</button></td>
          </tr>`;}).join('')}</tbody></table>
        ${!visible.length?'<div class="table-empty">ไม่มีทีมในหมวดนี้</div>':''}
      </div>
      <p class="page-foot">${icon('lock')} แสดงเฉพาะคะแนนของคุณที่ยืนยันส่งล่าสุด</p>`;
  }
  function criterionCard(teamId,c){
    const r=record(teamId);const current=isValidScore(r.draft?.[c.id])?r.draft[c.id]:(isValidScore(r.confirmed?.[c.id])?r.confirmed[c.id]:null);
    const noEdit=state.locked.includes(teamId)||state.published;
    const base=current===null?null:Math.floor(current);
    const halfActive=current!==null && current%1===.5;
    return `<section class="criterion"><div class="criterion-head"><div class="criterion-heading"><div class="criterion-symbol">${icon(c.icon)}</div><div><div class="criterion-label">${esc(c.name)}</div><div class="criterion-hint">น้ำหนัก ${c.weight}% · ${esc(c.description)}</div></div></div><div class="score-value" aria-live="polite">${current===null?'—':current.toFixed(1)} <small>/10</small></div></div><div class="score-grid" role="group" aria-label="ให้คะแนน ${esc(c.name)}">${Array.from({length:10},(_,i)=>i+1).map(v=>`<button type="button" class="score-btn ${base===v?'selected':''}" aria-pressed="${base===v?'true':'false'}" aria-label="${esc(c.name)} ให้ ${v} คะแนน${base===v&&halfActive?' บวกครึ่งคะแนนเป็น '+current.toFixed(1):''}" data-action="score-base" data-team="${teamId}" data-criterion="${c.id}" data-value="${v}" ${noEdit?'disabled':''}><span class="score-number">${v}</span>${base===v&&halfActive?'<span class="half-flag" aria-hidden="true">+½</span>':''}</button>`).join('')}</div><div class="extra-score"><span class="hint">แตะคะแนน 1–10 แล้วกด +0.5 ได้</span><div class="mini-actions"><button class="mini-btn ${halfActive?'on':''}" data-action="score-half" data-team="${teamId}" data-criterion="${c.id}" ${noEdit||current===10?'disabled':''}>+0.5 ${halfActive?'✓':''}</button></div></div></section>`;
  }
  function summaryPanel(score,confirmedScore,pending){
    return `<div class="summary-panel"><div class="suptitle"><span class="preview-spark">✧</span> คะแนนรวมของคุณ · ${score===null?'ยังไม่ครบ':'ตัวอย่าง'}</div>${score===null?'<h2 class="neutral-value">— / 100</h2><p>กรอกทุกเกณฑ์ก่อนจึงจะแสดงคะแนนรวม</p>':`<h2>${fixed(score)} <span style="font-size:.5em;font-weight:500">/ 100</span></h2><p>คะแนนของคุณเท่านั้น · ${pending?'การแก้ไขยังไม่ยืนยัน':'ยังไม่ใช่คะแนนรวมของกรรมการทั้งหมด'}</p>`}${confirmedScore!==null&&pending?`<div style="margin-top:12px;font-size:.79rem;color:#d8f1e5">Last Confirmed: <strong>${fixed(confirmedScore)} / 100</strong></div>`:''}</div>`;
  }
  function scoring(){
    const t=state.teams.find(x=>x.id===state.activeTeamId)||state.teams[0];
    const r=record(t.id);const draft={...(r.confirmed||{}),...(r.draft||{})};const completed=countScores(draft);const score=myTotal(draft);const confirmedScore=r.confirmed?myTotal(r.confirmed):null;
    const pending=isPending(t.id);const locked=state.locked.includes(t.id)||state.published;
    const canSubmit=!locked && score!==null && (!r.confirmed||pending);
    const order=String(state.teams.indexOf(t)+1).padStart(2,'0');const [st]=judgeStatus(t.id);
    const stTxt={'Locked':'ล็อกแล้ว','Pending Changes':'แก้ไขแล้ว ยังไม่ส่ง','Completed':'ส่งแล้ว','Draft':'แบบร่าง','Not Started':'ยังไม่เริ่ม'}[st]||st;
    return `${pageHead({title:`<span class="title-order">${order}</span> ${esc(t.name)}`,sub:`ลำดับนำเสนอ ${order} จาก ${state.teams.length} ทีม · สถานะ: ${stTxt}`,actions:`<button class="btn outline small" data-action="nav" data-target="judgeDashboard">${icon('back')} ทีมทั้งหมด</button>`})}${summaryBar({label:'ให้คะแนนแล้ว',done:completed,total:FINAL.length,unit:'เกณฑ์',detail:'เลือกคะแนน 1–10 และกด +0.5 ได้'})}<div class="judge-layout"><div class="judge-main"><div class="criteria-list">${FINAL.map(c=>criterionCard(t.id,c)).join('')}</div><div class="submit-bar"><span class="draft-indicator">${icon(locked?'lock':'checkcircle')} ${locked?'ล็อกแล้ว · ดูได้อย่างเดียว':REAL()?'บันทึกแบบร่างอัตโนมัติ':'บันทึกแบบร่างแล้ว (Demo)'}</span><button class="btn primary" data-action="submit" data-id="${t.id}" ${canSubmit?'':'disabled'}>${r.confirmed?'บันทึกการแก้ไข':'ตรวจสอบและส่งคะแนน'} ${icon('arrow')}</button></div></div><aside class="side-summary">${summaryPanel(score,confirmedScore,pending)}<div class="side-info"><h3>สรุปคะแนน</h3><div class="row"><span>ทีม</span><strong>${esc(t.name)}</strong></div><div class="row"><span>ลำดับนำเสนอ</span><strong>#${String(state.teams.indexOf(t)+1).padStart(2,'0')}</strong></div><div class="row"><span>กรอกคะแนน</span><strong>${completed} / ${FINAL.length}</strong></div><div class="row"><span>สถานะ</span><strong>${stTxt}</strong></div></div>${r.confirmed?`<div class="notice ${pending?'warn':''}">${icon('shield')} ${pending?'คุณมี Pending Changes ซึ่งยังไม่แทนที่คะแนนที่ยืนยันล่าสุด':'คะแนนชุดนี้เคย Confirm Submit แล้ว และแก้ไขได้จนกว่า Admin Lock'}</div>`:''}</aside></div>`;
  }
  function admin(){
    const completed=state.teams.filter(t=>allowedToLock(t.id)).length;
    const tabs=[['overview','ภาพรวม'],['teams','ทีมและลำดับ'],['demo','คะแนน Demo'],['weights','เกณฑ์และน้ำหนัก'],['tie','ตรวจคะแนนเสมอ']];
    return `${pageHead({title:'ควบคุมการแข่งขัน',sub:LIVE.on?'คะแนนจริงจากกรรมการ อัปเดตอัตโนมัติทุก 3 วินาที':ACCESS()?'โหมดทดสอบ: นับเฉพาะคะแนนที่กรอกบนเบราว์เซอร์นี้ ยังไม่เชื่อม server':'ข้อมูลทดสอบ ไม่ใช่กรรมการจริง',actions:`<button class="btn outline small" data-action="reset">${icon('reset')} ${LIVE.on?'Reset คะแนน':'Reset Demo'}</button>`})}${summaryBar({label:state.published?'ประกาศผลแล้ว · Lock':'Lock แล้ว',done:state.locked.length,total:state.teams.length,detail:`กรรมการส่งครบ ${completed} ทีม · กรรมการ ${JUDGE_TOTAL()} ท่าน · Demo ${state.demoWeight}% / Final ${100-state.demoWeight}%`})}${tabsRow(tabs,state.adminTab,'admin-tab','tab')}${state.adminTab==='overview'?adminOverview():state.adminTab==='teams'?adminTeams():state.adminTab==='demo'?adminDemo():state.adminTab==='tie'?adminTieReview():adminWeights()}`;
  }
  function adminOverview(){
    const allReady=state.teams.every(t=>allowedToLock(t.id));const allLocked=state.teams.every(t=>state.locked.includes(t.id));
    return `<div class="admin-section"><section class="panel"><div class="toolbar"><div><h3>สถานะการส่งคะแนน</h3><p class="muted" style="font-size:.81rem">ทุกทีมต้องได้รับ Confirmed Submission ${JUDGE_TOTAL()}/${JUDGE_TOTAL()} ก่อน Lock</p></div>${badge(REAL()?`กรรมการ ${JUDGE_TOTAL()} ท่าน`:'14 mock judges + 1 demo judge','outline')}</div><div class="card table-card"><table class="data-table"><thead><tr><th class="col-order">ลำดับนำเสนอ</th><th>ทีม</th><th>กรรมการส่งแล้ว</th><th>สถานะ</th><th>การทำงาน</th></tr></thead><tbody>${state.teams.map((t,i)=>`<tr><td class="col-order"><span class="order-no">${String(i+1).padStart(2,'0')}</span></td><td class="col-name"><strong>${esc(t.name)}</strong></td><td><div class="progress-cell">${progressBar(judgeCompletionCount(t.id),JUDGE_TOTAL(),'ส่งคะแนนแล้ว','progress--sm')}<strong>${judgeCompletionCount(t.id)}/${JUDGE_TOTAL()}</strong></div></td><td>${state.locked.includes(t.id)?`<span class="status status--locked">${icon('lock')}ล็อกแล้ว</span>`:allowedToLock(t.id)?`<span class="status status--done">${icon('check')}พร้อม Lock</span>`:'<span class="status status--draft">ยังส่งไม่ครบ</span>'}</td><td>${state.locked.includes(t.id)?`<button class="btn outline small" data-action="unlock-team" data-id="${t.id}" ${state.published?'disabled':''}>Unlock</button>`:`<button class="btn primary small" data-action="lock-team" data-id="${t.id}" ${allowedToLock(t.id)&&!state.published?'':'disabled'}>Lock</button>`}</td></tr>`).join('')}</tbody></table></div></section><aside style="display:grid;gap:14px"><div class="card card-pad"><h3>ควบคุมการประกาศผล</h3><p class="muted" style="font-size:.82rem;margin:6px 0 17px">${REAL()?'Lock ได้เมื่อกรรมการส่งคะแนนครบทุกท่าน แล้วจึง Publish':'เพื่อทดลอง Flow อย่างรวดเร็ว สามารถใส่คะแนนสมมติให้ครบทุกทีมได้'}</p><div style="display:grid;gap:9px"><button class="btn outline wide" data-action="simulate" ${state.published?'disabled':''}>${icon('spark')} เติมคะแนนจำลองให้ครบ</button><button class="btn outline wide" data-action="lock-all" ${allReady&&!allLocked&&!state.published?'':'disabled'}>${icon('lock')} Lock All Teams</button><button class="btn primary wide" data-action="publish" ${allLocked&&!state.published&&!hasTopTie()?'':'disabled'}>${icon('trophy')} Publish Results ${icon('arrow')}</button><button class="btn light wide" data-action="preview-stage">${icon('eye')} Preview Results (Admin)</button></div></div><div class="admin-brief"><h3>ความพร้อมก่อนประกาศผล</h3><p>${allReady?'✓ Confirmed submissions ครบทุกทีม':'• ยังมีคะแนนที่ไม่ได้ Confirm Submit'}<br/>${allLocked?'✓ Lock ทุกทีมแล้ว':'• ต้อง Lock ทุกทีม'}<br/>${hasTopTie()?'! มี Tie กระทบ Top 3 ที่ต้องตัดสิน':(REAL()?'✓ ไม่มี Tie กระทบ Top 3':'✓ ไม่มี Tie กระทบ Top 3 ในข้อมูลจำลอง')}</p></div>${REAL()?'':`<div class="notice">${icon('shield')} ก่อน Publish ผลจริงจะต้องตรวจสิทธิ์ Admin, rubric version, audit logs และข้อมูลคะแนนจาก Server — สิ่งเหล่านี้ยังไม่เชื่อมใน Demo</div>`}</aside></div>`;
  }
  function adminTeams(){return `<div class="panel"><div class="toolbar"><div><h3>Teams & Presentation Order</h3><p class="muted" style="font-size:.82rem">เรียงตามผลจับฉลาก กรรมการยังสามารถเลือกประเมินทีมใดก่อนก็ได้</p></div>${badge(`${state.teams.length} Teams`,'good')}</div><div class="card table-card"><table class="data-table"><thead><tr><th class="col-order">ลำดับนำเสนอ</th><th>ทีม</th><th>เลื่อนขึ้น</th><th>เลื่อนลง</th></tr></thead><tbody>${state.teams.map((t,i)=>`<tr><td class="col-order"><span class="order-no">${String(i+1).padStart(2,'0')}</span></td><td class="col-name"><strong>${esc(t.name)}</strong></td><td><button class="btn outline small" data-action="move-team" data-id="${t.id}" data-dir="-1" ${i===0||state.published?'disabled':''}>↑</button></td><td><button class="btn outline small" data-action="move-team" data-id="${t.id}" data-dir="1" ${i===state.teams.length-1||state.published?'disabled':''}>↓</button></td></tr>`).join('')}</tbody></table></div><div class="admin-setting-row" style="margin-top:18px"><input class="input" style="max-width:330px" data-input="new-team" value="${esc(state.newTeamName||'')}" placeholder="ชื่อทีมใหม่..." aria-label="ชื่อทีมใหม่"/><button class="btn primary" data-action="add-team" ${state.published?'disabled':''}>+ เพิ่มทีละทีม</button></div><p class="small-gray" style="margin-top:10px">ทีมใหม่จะถูกเพิ่มท้าย Presentation Order และนับรวมในเงื่อนไข Lock All</p></div>`;}
  function adminDemo(){return `<div class="panel"><div class="toolbar"><div><h3>Demo Round · Pre-aggregated Averages</h3><p class="muted" style="font-size:.83rem">แก้ไขค่าเฉลี่ยรายทีมรายเกณฑ์ได้เอง (0–10 พร้อมทศนิยม)</p></div><button class="btn outline small" data-action="download-csv">${icon('download')} CSV Template</button></div><div class="card table-card"><table class="data-table"><thead><tr><th>Team</th>${DEMO.map(c=>`<th>${esc(c.name)} (${c.weight}%)</th>`).join('')}<th>Demo /100</th></tr></thead><tbody>${state.teams.map(t=>`<tr><td><strong>${esc(t.name)}</strong></td>${DEMO.map(c=>`<td><input class="input" style="width:100px;min-height:36px;padding:6px" type="number" min="0" max="10" step="any" value="${state.demoScores[t.id]?.[c.id]??0}" data-demo-team="${t.id}" data-demo-criterion="${c.id}" ${state.published?'disabled':''}/></td>`).join('')}<td><strong>${fixed(demoScore(t.id))}</strong></td></tr>`).join('')}</tbody></table></div><div class="admin-setting-row" style="margin-top:18px"><label class="btn outline" for="csv-file">${icon('upload')} Upload CSV</label><input id="csv-file" data-input="csv-file" type="file" accept=".csv,text/csv" hidden ${state.published?'disabled':''}/><span class="small-gray">Demo นี้รองรับ CSV; Excel (.xlsx) ต้องเพิ่มเมื่อเชื่อม Backend จริง</span></div></div>`;}
  function adminWeights(){return `<div class="card card-pad"><h3>Demo / Final Day Round Weights</h3><p class="muted" style="font-size:.86rem;margin:7px 0 18px">ค่าเริ่มต้น 20 / 80 เปลี่ยนได้ใน Demo; คะแนนรวมจะคำนวณใหม่โดยไม่แก้คะแนนที่กรรมการยืนยัน</p><div class="chip-row" style="margin-bottom:20px">${[10,20,30,40,50].map(n=>`<button class="chip ${state.demoWeight===n?'active':''}" data-action="set-weight" data-weight="${n}">Demo ${n}% / Final ${100-n}%</button>`).join('')}</div><div class="stat-strip" style="max-width:650px;grid-template-columns:repeat(2,1fr)"><div class="stat"><span>Demo Round</span><strong>${state.demoWeight}%</strong></div><div class="stat"><span>Final Day</span><strong>${100-state.demoWeight}%</strong></div></div><div class="mini-divider"></div><div class="admin-section" style="margin-bottom:18px"><div><h3>Demo Day Criteria · by Project Sponsor</h3><div class="card table-card"><table class="data-table"><thead><tr><th>Criterion</th><th>Weight</th><th>รายละเอียด</th></tr></thead><tbody>${DEMO.map(c=>`<tr><td><strong>${esc(c.name)}</strong></td><td>${c.weight}%</td><td style="white-space:normal;min-width:220px">${esc(c.description||'')}</td></tr>`).join('')}<tr><td><strong>รวม</strong></td><td><strong>${DEMO.reduce((s,c)=>s+c.weight,0)}%</strong></td><td></td></tr></tbody></table></div></div></div><div class="admin-section"><div><h3>Pitching Day (Final Day) Criteria · by คณะกรรมการ</h3><div class="card table-card"><table class="data-table"><thead><tr><th>Criterion</th><th>Weight</th><th>รายละเอียด</th><th>Score Range</th></tr></thead><tbody>${FINAL.map(c=>`<tr><td><strong>${esc(c.name)}</strong></td><td>${c.weight}%</td><td style="white-space:normal;min-width:200px">${esc(c.description||'')}</td><td>0–10, 0.5 steps</td></tr>`).join('')}<tr><td><strong>รวม</strong></td><td><strong>${FINAL.reduce((s,c)=>s+c.weight,0)}%</strong></td><td></td><td></td></tr></tbody></table></div></div><div class="admin-brief"><h3>Important</h3><p>นี่เป็น Prototype สำหรับทดสอบ UX; การเพิ่ม/ลบ Criteria, versioning, reconfirmation, การกำหนดสิทธิ์ Super Admin และ Audit Log จะเป็นส่วนของระบบ Production</p></div></div></div>`;}
  function adminTieReview(){const list=ranked(),groups=[];for(let i=1;i<list.length;i++){if(list[i].overall===list[i-1].overall && (list[i].rank<=3||list[i-1].rank<=3)){groups.push([list[i-1],list[i]])}}return `<div class="tie-review-workspace"><div class="tie-review-header"><div class="tie-review-seal">${icon('trophy')}</div><div><div class="section-eyebrow">PRIVATE · ADMIN ONLY</div><h3>Top 3 Tie Review</h3><p>ตรวจสอบคะแนนที่เสมอกันก่อนเผยแพร่ผล โดยไม่เปลี่ยนคะแนนที่คำนวณได้</p></div></div>${groups.length?groups.map(g=>`<div class="tie-review-sample"><div class="tie-alert">${icon('warning')} คะแนนเสมอที่กระทบ Top 3: ${esc(g[0].name)} และ ${esc(g[1].name)}</div><div class="tie-sample-grid">${g.map(t=>`<div class="tie-team"><strong>${esc(t.name)}</strong><span>${fixed(t.overall)} / 100</span></div>`).join('')}</div><p class="small-gray">โปรโตไทป์นี้ตรวจจับ Tie แต่ยังไม่มีฟอร์มจัดอันดับแทนการตัดสินของ Admin; ต้องพัฒนา Workflow อนุมัติอันดับพร้อม Audit ก่อนใช้งานจริง</p></div>`).join(''):`<div class="tie-review-empty"><div class="tie-review-check">${icon('checkcircle')}</div><h4>No Top 3 tie detected</h4><p>${REAL()?'จากคะแนนจริงของกรรมการ':'จากคะแนนจำลองในเบราว์เซอร์นี้'} ยังไม่พบคะแนนเสมอที่กระทบอันดับ 1–3</p><div class="tie-demo-example"><span class="mini-chip">UX Scenario Preview</span><div class="tie-sample-grid"><div class="tie-team"><strong>ทีมตัวอย่าง A</strong><span>86.00 / 100</span></div><div class="tie-team"><strong>ทีมตัวอย่าง B</strong><span>86.00 / 100</span></div></div><small>กรณีตัวอย่างที่ต้องส่งกลับให้กรรมการทบทวน ก่อน Admin จัดลำดับพร้อมบันทึกเหตุผล</small></div></div>`}</div>`;}
  function stage(){
    const list=ranked();const preview=state.preview&&!state.published;
    return `${pageHead({title:state.stageShot===1?'ประกาศผล · Top 5':'ประกาศผล · คะแนนละเอียด',sub:preview?'Admin Preview · ยังไม่เปิดเผยต่อสาธารณะ':'เผยแพร่แล้ว',actions:`<button class="btn ${state.stageShot===1?'primary':'outline'} small" data-action="stage-shot" data-shot="1">Top 5</button><button class="btn ${state.stageShot===2?'primary':'outline'} small" data-action="stage-shot" data-shot="2">คะแนนละเอียด</button><button class="btn outline small" data-action="fullscreen">${icon('fullscreen')} Fullscreen</button><button class="btn outline small" data-action="nav" data-target="admin">${icon('back')} ภาพรวม</button>`})}${state.stageShot===1?stage1(list,preview):stage2(list,preview)}<p class="footer-note">${REAL()?'* คะแนนเฉลี่ยจากกรรมการทุกท่าน · ไม่เปิดเผยคะแนนของกรรมการรายบุคคล':'* คะแนนและทีมทั้งหมดเป็นข้อมูลสมมติสำหรับทดสอบหน้าจอ · ไม่เปิดเผยคะแนนของกรรมการรายบุคคล'}</p>`;
  }
  function medalGraphic(rank) {
    const metal=rank===1?['#fff0ad','#edbe50','#986b25']:rank===2?['#fcfffc','#b5c9ca','#6d8e8a']:['#fff2e5','#db9e74','#92573e'];
    const id='metal-'+rank;
    return `<span class="medal" aria-label="อันดับ ${rank}"><svg viewBox="0 0 120 120" role="img" aria-hidden="true"><defs><radialGradient id="${id}" cx=".34" cy=".25" r=".82"><stop offset="0" stop-color="${metal[0]}"/><stop offset=".54" stop-color="${metal[1]}"/><stop offset="1" stop-color="${metal[2]}"/></radialGradient><linearGradient id="${id}-ring" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#fffce5"/><stop offset=".33" stop-color="${metal[1]}"/><stop offset=".65" stop-color="${metal[2]}"/><stop offset="1" stop-color="#fff5c8"/></linearGradient></defs><path d="M34 77 L23 108 42 98 54 113 60 86 M86 77 L97 108 78 98 66 113 60 86" fill="${metal[2]}" opacity=".84"/><circle cx="60" cy="52" r="45" fill="url(#${id}-ring)"/><circle cx="60" cy="52" r="39.2" fill="url(#${id})" stroke="#ffffffa8" stroke-width="2"/><circle cx="60" cy="52" r="32" fill="none" stroke="#ffffff8a" stroke-width="1.4"/><path d="M33 45 C42 20 64 18 80 28" fill="none" stroke="#ffffffe0" stroke-width="3" stroke-linecap="round" opacity=".62"/><text x="60" y="69" font-family="var(--font-ui)" text-anchor="middle" font-size="50" font-weight="bold" fill="#194932">${rank}</text></svg></span>`;
  }
  /* Final Results · Top 5 award stage.
     Data: ranked() (overall rounded to 2 dp, shared rank on equal overall).
     Card slot (position/size) comes from list order; tier, number and label come from the rank,
     so tied teams share a number and a metal. */
  const AWARD_LABEL={1:'CHAMPION',2:'SECOND PLACE',3:'THIRD PLACE',4:'FOURTH PLACE',5:'FIFTH PLACE'};
  const AWARD_TIER={1:'gold',2:'silver',3:'copper'};
  function hasResult(teamId){return REAL()?judgeCompletionCount(teamId)>0:true;}
  function awardScore(v){return v===null||v===undefined||!Number.isFinite(Number(v))?'—':Number(v).toFixed(2);}
  function awardEntries(list){
    const scored=list.filter(t=>hasResult(t.id));
    if(!scored.length)return [1,2,3,4,5].map(n=>({id:'empty-'+n,name:'รอผลคะแนน',rank:n,overall:null,placeholder:true}));
    let rank=0;const ranked=scored.map((t,i)=>{if(i===0||t.overall!==scored[i-1].overall)rank=i+1;return {...t,rank};});
    return ranked.filter((t,i)=>i<5||t.rank<=5);
  }
  function awardCard(t,slot,list){
    const tier=t.rank<=3?AWARD_TIER[t.rank]:'finalist';const tie=!t.placeholder&&list.filter(x=>x.rank===t.rank).length>1;
    const len=[...String(t.name)].length;const size=len<=9?'xl':len<=15?'lg':'md';
    const label=(AWARD_LABEL[t.rank]||`RANK ${t.rank}`)+(tie?' · TIE':'');
    return `<li class="award-card award-card--${tier} award-slot-${slot}${t.placeholder?' is-placeholder':''}" aria-label="อันดับ ${t.rank}${tie?' (คะแนนเท่ากัน)':''}: ${esc(t.name)}, คะแนน ${awardScore(t.overall)} จาก 100">
      <span class="award-sheen" aria-hidden="true"></span>
      <span class="rank-pennant" aria-hidden="true">${String(t.rank).padStart(2,'0')}</span>
      <span class="award-label">${label}</span>
      <h2 class="award-team award-team--${size}">${esc(t.name)}</h2>
      <span class="award-divider" aria-hidden="true"></span>
      <p class="award-score"><strong>${awardScore(t.overall)}</strong><span> / 100</span></p>
      <span class="award-score-label">OVERALL SCORE</span>
    </li>`;
  }
  function stage1(list,preview){
    const entries=awardEntries(list);const podium=entries.slice(0,3);const finalists=entries.slice(3);
    const demo=!REAL();const empty=entries[0]?.placeholder;
    const badge=preview?'ADMIN PREVIEW':demo?'DEMO DATA':'';
    const note=empty?'ยังไม่มีคะแนนที่กรรมการยืนยัน — ผลจะแสดงเมื่อมีคะแนน'
      :preview?'ตัวอย่างก่อนประกาศผล — ยังไม่ใช่ผลอย่างเป็นทางการ'
      :demo?'ข้อมูลจำลองสำหรับทดสอบหน้าจอ — ไม่ใช่ผลการแข่งขันจริง'
      :`ผลอย่างเป็นทางการ · Demo ${state.demoWeight}% + Pitching Day ${100-state.demoWeight}% · คะแนนเฉลี่ยจากกรรมการ ${JUDGE_TOTAL()} ท่าน`;
    return `<div class="awards-shell"><section class="awards-stage" aria-labelledby="awards-title">
      <header class="awards-header">
        <p class="awards-kicker">KASSET · PI CHAMPION SEASON 2</p>
        ${badge?`<span class="awards-badge">${badge}</span>`:''}
        <h1 id="awards-title" class="awards-title">Final Results</h1>
        <span class="awards-top-tag">TOP 5</span>
      </header>
      <ol class="awards-podium" aria-label="อันดับ 1 ถึง 3">${podium.map((t,i)=>awardCard(t,i+1,entries)).join('')}</ol>
      ${finalists.length?`<ol class="awards-finalists" start="${finalists[0].rank}" style="--n:${finalists.length}" aria-label="อันดับ 4 ถึง 5">${finalists.map((t,i)=>awardCard(t,i+4,entries)).join('')}</ol>`:''}
      <footer class="awards-footer"><span class="awards-floor" aria-hidden="true"></span><p>${note}</p></footer>
    </section></div>`;
  }
  function stage2(list,preview){
    return `<section class="stage results-stage">${wave()}${preview?'<div class="preview-stamp">ADMIN PREVIEW · NOT PUBLIC</div>':''}<div class="stage-inner"><div class="stage-heading"><div class="kicker">KAsset · PI CHAMPION SEASON 2</div><h1>Detailed Final Results</h1><p>ค่าเฉลี่ยแยกตามเกณฑ์ของทุกทีม · Demo ${state.demoWeight}% + Final Day ${100-state.demoWeight}%</p></div><div class="table-wrap results-table-shell" style="border:0"><table class="results-table"><thead><tr class="results-group-row"><th colspan="2" class="group-rank">TEAM &amp; RANK</th><th colspan="${DEMO.length+1}" class="group-demo">DEMO ROUND · ${state.demoWeight}%</th><th colspan="${FINAL.length+1}" class="group-final">FINAL DAY · ${100-state.demoWeight}%</th><th class="group-overall">OVERALL</th></tr><tr><th>Rank</th><th>Team</th>${DEMO.map(c=>`<th>Demo<br/>${esc(c.name)}<br/>AVG</th>`).join('')}<th>Demo<br/>Score</th>${FINAL.map(c=>`<th>Final<br/>${esc(c.name)}<br/>AVG</th>`).join('')}<th>Final Day<br/>Score</th><th>Final<br/>Score</th></tr></thead><tbody>${list.map((t,i)=>`<tr class="${i<3?'top':''}"><td>${i<3?`<span class="rank-emblem rank-${i+1}">${i+1}</span>`:t.rank}</td><td class="team-col">${esc(t.name)}</td>${DEMO.map(c=>`<td>${fixed(state.demoScores[t.id]?.[c.id]??0)}</td>`).join('')}<td><strong>${fixed(t.demo)}</strong></td>${FINAL.map(c=>`<td>${fixed(averageFinalCriterion(t.id,c.id))}</td>`).join('')}<td><strong>${fixed(t.final)}</strong></td><td>${fixed(t.overall)}</td></tr>`).join('')}</tbody></table></div><div class="results-foot">แสดงเฉพาะค่าเฉลี่ยรายเกณฑ์ ไม่มีชื่อหรือคะแนนรายกรรมการ · คำนวณเต็มความละเอียดและปัด Overall Score 2 ตำแหน่งก่อนจัดอันดับ</div></div></section>`;
  }
  function dialog(){const d=state.dialog;if(!d)return '';
    let title='',body='',confirm='ยืนยัน',warning=false;
    if(d.type==='submit'){
      const t=state.teams.find(t=>t.id===d.teamId);const scores=record(d.teamId).draft;const total=myTotal(scores);
      title=d.isEdit?'Confirm Save Changes':'Confirm Your Scores';confirm=d.isEdit?'Save Changes':'Confirm Submit';
      body=`<p>ตรวจคะแนนของ ${esc(t.name)} ก่อนยืนยัน — ค่าที่เห็นเป็นคะแนนของคุณเท่านั้น</p><div class="modal-table">${FINAL.map(c=>`<div class="modal-row"><span>${esc(c.name)} <small>(${c.weight}%)</small></span><strong>${scores[c.id]===undefined?'—':scores[c.id].toFixed(1)} / 10</strong></div>`).join('')}</div><div class="modal-total"><span>MY TOTAL · ${d.isEdit?'NEW PREVIEW':'PREVIEW'}</span><strong>${fixed(total)} /100</strong></div>${d.isEdit?'<p style="margin-top:9px">Last Confirmed จะถูกแทนที่เมื่อกด Save Changes สำเร็จเท่านั้น</p>':'<p style="margin-top:9px">เมื่อ Confirm สำเร็จ สถานะจะเป็น Completed แต่กลับมาแก้ไขได้ก่อน Admin Lock</p>'}`;
    } else if(d.type==='simulate'){title='เติมคะแนนทดสอบให้ครบทุกทีม?';body='<p>ระบบจะใส่คะแนนสมมติแทนการประเมินของ Judge 01 สำหรับทีมที่ยังไม่ Submit เพื่อทดลอง Lock และ Publish — ไม่มีการบันทึกข้อมูลจริง</p>';confirm='เติมคะแนนจำลอง';}
    else if(d.type==='lockTeam'){title='Confirm Lock Team';const t=state.teams.find(x=>x.id===d.teamId);body=`<p>ล็อก ${esc(t.name)} แล้วกรรมการจะไม่สามารถแก้คะแนนได้จนกว่า Admin จะ Unlock ก่อน Publish</p><div class="notice">Completed ${judgeCompletionCount(d.teamId)}/${JUDGE_TOTAL()}</div>`;confirm='Confirm Lock';}
    else if(d.type==='unlockTeam'){title='Confirm Unlock Team';body='<p>Unlock ทีมนี้เพื่อให้กรรมการกลับมาแก้คะแนนได้ก่อน Publish</p>';confirm='Confirm Unlock';}
    else if(d.type==='lockAll'){title='Confirm Lock All';body='<p>ปิดการให้คะแนนของทุกทีมพร้อมกัน หลังจากกรรมการทั้งหมด Submit ครบแล้ว</p>';confirm='Lock All';}
    else if(d.type==='publish'){title='Publish Final Results?';body='<p>หลัง Publish แล้วจะไม่สามารถแก้คะแนนหรือ Unlock ได้อีก การแสดงผลจะเริ่มที่ Shot 1 (Top 5) และสามารถเปลี่ยนเป็น Shot 2 ได้</p>';confirm='Publish (Demo)';warning=true;}
    else if(d.type==='reset'&&LIVE.on){title='ล้างคะแนนกรรมการทั้งหมด?';body=`<p>ใช้สำหรับช่วงทดสอบ — คะแนนแบบร่างและคะแนนที่ส่งแล้วของกรรมการทุกท่าน (${JUDGE_TOTAL()} ท่าน) จะถูกล้าง, ทุกทีมจะถูกปลด Lock และยกเลิกการประกาศผล</p><p>ลำดับทีม คะแนน Demo และน้ำหนักคะแนนยังอยู่เหมือนเดิม · ระบบสำรองข้อมูลเดิมไว้ในโฟลเดอร์ data/backups ก่อนล้าง</p><div class="notice warn">${icon('warning')} ห้ามกดในวันงานจริงหลังกรรมการเริ่มให้คะแนนแล้ว</div><label class="reset-confirm"><span>พิมพ์ <strong>RESET</strong> เพื่อยืนยัน</span><input class="input" data-input="reset-confirm" autocomplete="off" autocapitalize="characters" spellcheck="false" value="${esc(state.resetConfirm||'')}" placeholder="RESET"/></label>`;confirm='ล้างคะแนน';warning=true;}
    else if(d.type==='reset'){title='รีเซ็ตข้อมูล Demo?';body='<p>คะแนน Draft, Confirmed, Lock, ตารางคะแนน และการตั้งค่าทั้งหมดในเบราว์เซอร์นี้จะถูกคืนค่าเริ่มต้น</p>';confirm='รีเซ็ต';warning=true;}
    else if(d.type==='import'){title=`ยืนยัน Import CSV (${d.rows.length} ทีม)`;body=`<p>ระบบจะเขียนทับ Demo Averages ของ ${d.rows.length} ทีมที่มีอยู่ในไฟล์ พร้อมคำนวณคะแนนใหม่</p>${LIVE.on?'':'<div class="notice">Import นี้เป็นการจำลองในเบราว์เซอร์เท่านั้น</div>'}`;confirm='ยืนยัน Import';}
    return `<div class="modal-backdrop" role="presentation" data-action="dismiss-backdrop"><div class="modal" tabindex="-1" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="kicker">PI CHAMPION · ${warning?'IMPORTANT ACTION':'CONFIRMATION'}</div><h2 id="dialog-title">${title}</h2>${body}<div class="modal-actions"><button class="btn outline" data-action="close-dialog">กลับไปแก้ไข</button><button class="btn ${warning?'primary':'primary'}" data-action="confirm-dialog" ${d.type==='reset'&&LIVE.on&&(state.resetConfirm||'').trim().toUpperCase()!=='RESET'?'disabled':''}>${confirm} ${icon('check')}</button></div></div></div>`;
  }
  function render(){
    const focused=document.activeElement;
    const scoreFocus=focused?.dataset?.action?.startsWith('score-')?{action:focused.dataset.action,team:focused.dataset.team,criterion:focused.dataset.criterion,value:focused.dataset.value}:null;
    const hadModal=!!document.querySelector('.modal');
    state.screen=allowedScreen(state.screen);
    let content='';switch(state.screen){case 'home':content=home();break;case 'judgeAccess':case 'adminAccess':content=access();break;case 'judgeDashboard':content=judgeDashboard();break;case 'scoring':content=scoring();break;case 'admin':content=admin();break;case 'stage':content=stage();break;default:content=home();}
    if(document.body?.dataset) document.body.dataset.screen=state.screen;
    app.innerHTML=`${metaHead()}<main class="shell">${content}</main>${dialog()}${state.toast?`<div class="toast-area" aria-live="polite"><div class="toast">${esc(REAL()?state.toast.replace(/\s*\((Demo|ข้อมูลจำลอง)\)/g,'').replace('ผลคะแนนจำลอง','ผลคะแนน'):state.toast)} <button type="button" style="float:right;border:0;background:transparent;color:white;margin-left:13px" data-action="close-toast" aria-label="ปิดข้อความ">×</button></div></div>`:''}`;
    window.PIChampionRibbon3D?.sync?.();
    if(state.dialog && !hadModal) requestAnimationFrame(()=>app.querySelector('.modal')?.focus({preventScroll:true}));
    if(scoreFocus){
      const matching=Array.from(app.querySelectorAll('[data-action]')).find(b=>b.dataset.action===scoreFocus.action && b.dataset.team===scoreFocus.team && b.dataset.criterion===scoreFocus.criterion && b.dataset.value===scoreFocus.value);
      if(matching && !matching.disabled) matching.focus({preventScroll:true});
    }
  }
  function generateCsv(){const rows=[['team_id',...DEMO.map(c=>c.id)],...state.teams.map(t=>[t.id,...DEMO.map(c=>state.demoScores[t.id]?.[c.id]??0)])];const data=rows.map(x=>x.join(',')).join('\r\n');const blob=new Blob([data],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='pi_champion_demo_scores_template.csv';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);}
  function handleCsv(file){if(!file)return;const reader=new FileReader();reader.onload=()=>{
    try {const lines=String(reader.result).replace(/^\uFEFF/,'').trim().split(/\r?\n/);const headings=lines.shift().split(',').map(x=>x.trim().toLowerCase());const expected=['team_id',...DEMO.map(c=>c.id)];if(expected.some(x=>!headings.includes(x)))throw new Error('CSV ต้องมีคอลัมน์ team_id,'+DEMO.map(c=>c.id).join(',')+'');
      const rows=[];for(const line of lines){if(!line.trim())continue;const parts=line.split(',');const values=Object.fromEntries(headings.map((h,i)=>[h,(parts[i]||'').trim()]));const id=Number(values.team_id);if(!state.teams.some(t=>t.id===id))throw new Error(`ไม่พบ Team ID ${id}`);const scores={};for(const c of DEMO){const n=Number(values[c.id]);if(!Number.isFinite(n)||n<0||n>10||values[c.id]==='')throw new Error(`คะแนน ${c.id} ของ Team ${id} ต้องอยู่ 0–10`);scores[c.id]=n;}rows.push({teamId:id,scores});}if(!rows.length)throw new Error('ไฟล์ CSV ไม่มีข้อมูล');if(new Set(rows.map(x=>x.teamId)).size!==rows.length)throw new Error('พบ team_id ซ้ำกัน');state.dialog={type:'import',rows};render();
    } catch(e){toast('Import CSV ไม่สำเร็จ: '+e.message);}
  };reader.readAsText(file,'UTF-8');}
  app.addEventListener('input',e=>{const el=e.target;if(el.matches('[data-input="code"]')){state.codeInput=el.value;}if(el.matches('[data-input="new-team"]')){state.newTeamName=el.value;}if(el.matches('[data-input="reset-confirm"]')){state.resetConfirm=el.value;const b=document.querySelector('.modal [data-action="confirm-dialog"]');if(b)b.disabled=el.value.trim().toUpperCase()!=='RESET';}});
  app.addEventListener('change',e=>{const el=e.target;if(el.matches('[data-demo-team]')){const id=Number(el.dataset.demoTeam);const c=el.dataset.demoCriterion;const val=Number(el.value);if(el.value.trim()===''||!Number.isFinite(val)||val<0||val>10){toast('คะแนน Demo ต้องอยู่ระหว่าง 0–10');return;}state.demoScores[id]={...state.demoScores[id],[c]:val};save();render();}if(el.matches('[data-input="csv-file"]'))handleCsv(el.files?.[0]);});
  app.addEventListener('click',e=>{
    const btn=e.target.closest('[data-action]');if(!btn)return;const a=btn.dataset.action;
    if(a==='dismiss-backdrop'){if(e.target===btn)closeDialog();return;}
    if(a==='close-dialog'){closeDialog();return;}
    if(a==='confirm-dialog'){confirmDialog();return;}
    if(a==='close-toast'){state.toast='';render();return;}
    if(a==='nav'){changeScreen(btn.dataset.target);return;}
    if(a==='brand-home'){if(APP==='admin')state.adminTab='overview';changeScreen(DASHBOARD);return;}
    if(a==='logout'&&LIVE.on){liveLogout();return;}
    if(a==='logout'){state.auth={...(state.auth||{}),[APP]:false};changeScreen(LOGIN);return;}
    if(a==='access-judge'){state.codeInput='';changeScreen('judgeAccess');return;}
    if(a==='access-admin'){state.codeInput='';changeScreen('adminAccess');return;}
    if(a==='fill-code'){state.codeInput=btn.dataset.code;render();return;}
    if(a==='login'&&LIVE.on){liveLogin();return;}
    if(a==='login'&&ACCESS()){staticLogin();return;}
    if(a==='login'){const role=APP;const expected=role==='admin'?'ADMINDEMO':'JUDGE01';if(state.codeInput.trim().toUpperCase()!==expected){toast(`รหัส Demo ไม่ถูกต้อง — ใช้ ${expected}`);return;}state.auth={...(state.auth||{}),[APP]:true};state.codeInput='';changeScreen(DASHBOARD);return;}
    if(a==='head-nav'){const target=btn.dataset.target;if(target==='judgeDashboard'){changeScreen('judgeDashboard');return;}if(target==='admin'){changeScreen('admin');return;}if(target==='stage'){if(state.published){state.preview=false;changeScreen('stage');}else{toast('ยังไม่ได้ Publish: กรุณาเข้า Admin เพื่อเปิด Preview แบบส่วนตัว');}return;}}
    if(a==='filter'){state.filter=btn.dataset.filter;save();render();return;}
    if(a==='select-team'){selectTeam(Number(btn.dataset.id));return;}
    if(a==='score-base'){setScore(Number(btn.dataset.team),btn.dataset.criterion,Number(btn.dataset.value));return;}
    if(a==='score-half'){const id=Number(btn.dataset.team),c=btn.dataset.criterion;const r=record(id);const current=r.draft?.[c]??r.confirmed?.[c]??null;const next=current===null?.5:(current%1===.5?Math.floor(current):Math.min(10,current+.5));setScore(id,c,next);return;}
    if(a==='submit'){const id=Number(btn.dataset.id);const r=record(id);if(myTotal(r.draft)===null)return toast('กรุณากรอกทุกเกณฑ์ก่อน Submit');openDialog('submit',id);state.dialog.isEdit=!!r.confirmed;render();return;}
    if(a==='admin-tab'){state.adminTab=btn.dataset.tab;save();render();return;}
    if(a==='simulate'){openDialog('simulate');return;}
    if(a==='lock-team'){openDialog('lockTeam',Number(btn.dataset.id));return;}
    if(a==='unlock-team'){openDialog('unlockTeam',Number(btn.dataset.id));return;}
    if(a==='lock-all'){openDialog('lockAll');return;}
    if(a==='publish'){openDialog('publish');return;}
    if(a==='preview-stage'){state.preview=!state.published;state.stageShot=1;changeScreen('stage');return;}
    if(a==='stage-shot'){state.stageShot=Number(btn.dataset.shot);save();render();return;}
    if(a==='fullscreen'){const target=document.querySelector('.awards-shell,.stage');if(document.fullscreenElement)document.exitFullscreen?.();else target?.requestFullscreen?.();return;}
    if(a==='move-team'){const idx=state.teams.findIndex(t=>t.id===Number(btn.dataset.id)),next=idx+Number(btn.dataset.dir);if(next<0||next>=state.teams.length||state.published)return;[state.teams[idx],state.teams[next]]=[state.teams[next],state.teams[idx]];save();render();return;}
    if(a==='add-team'){if(state.published)return toast('ประกาศผลแล้ว ไม่สามารถเพิ่มทีมได้');const name=(state.newTeamName||'').trim();if(!name)return toast('กรุณากรอกชื่อทีม');if(state.teams.some(t=>t.name.toLowerCase()===name.toLowerCase()))return toast('มีชื่อทีมนี้แล้ว');const id=Math.max(...state.teams.map(t=>t.id))+1;state.teams.push({id,name});state.demoScores[id]=LIVE.on?{}:defaultDemo(state.teams.length-1);state.newTeamName='';save();toast('เพิ่มทีม '+name+' สำเร็จ (Demo)');return;}
    if(a==='download-csv'){generateCsv();return;}
    if(a==='set-weight'){state.demoWeight=Number(btn.dataset.weight);save();render();return;}
    if(a==='reset'){state.resetConfirm='';openDialog('reset');return;}
  });
  document.addEventListener('keydown',e=>{
    if(e.key==='Enter'&&e.target?.matches?.('[data-input="code"]')){e.preventDefault();app.querySelector('[data-action="login"]')?.click();return;}
    if(e.key==='Escape'&&state.dialog){closeDialog();return;}
    if(e.key==='Tab'&&state.dialog){
      const modal=app.querySelector('.modal');if(!modal)return;
      const allowed=Array.from(modal.querySelectorAll('button:not(:disabled),input:not(:disabled),a[href]'));
      if(!allowed.length){e.preventDefault();modal.focus();return;}
      if(e.shiftKey && document.activeElement===allowed[0]){e.preventDefault();allowed[allowed.length-1].focus();}
      else if(!e.shiftKey && document.activeElement===allowed[allowed.length-1]){e.preventDefault();allowed[0].focus();}
    }
  });
  (async()=>{
    await detectLive();
    if(!LIVE.on&&ACCESS())document.documentElement.dataset.real='1';
    state.screen=allowedScreen(screenFromHash()||state.screen);
    writeHash(false);save();
    render();
  })();
})();
